"""Small immutable contracts, with unknown measurements represented by None."""
from dataclasses import asdict, dataclass
import hashlib


def digest(text):
    return hashlib.sha256(text.encode('utf-8', errors='surrogatepass')).hexdigest()


@dataclass(frozen=True)
class InputSnapshot:
    sha256: str
    characters: int
    local_tokens: int | None = None
    measurement: str = 'local_estimate_not_platform_usage'

    @classmethod
    def capture(cls, text, count_tokens=None):
        count = None
        if callable(count_tokens):
            try:
                value = count_tokens(text)
                count = value if type(value) is int and value >= 0 else None
            except Exception:
                pass
        return cls(digest(text), len(text), count)

    def to_dict(self):
        return asdict(self)

