"""Conservative, bounded, standard-library-only advisory detection.

No fuzzy matching, model inference, raw-text evidence, or mutation. A content
signal is not proof that compression is safe or that an account saves quota.
"""
import json
import re

MAX_SCAN_CHARS = 200000
_JSON_FENCE = re.compile(r'^ {0,3}```json[ \t]*\r?\n(.*?)^ {0,3}```[ \t]*(?:\r?\n|$)',
                         re.M | re.S | re.I)


def _outside_whitespace(body):
    quoted = escaped = False
    count = 0
    for char in body:
        if quoted:
            if escaped:
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '"':
                quoted = False
        elif char == '"':
            quoted = True
        elif char in ' \t\r\n':
            count += 1
    return count


def _reject_constant(value):
    raise ValueError('Not JSON')


def detect(text: str, context: dict | None = None) -> list[dict]:
    """Return metadata-only findings. Ordinary chat has no default treatment.

    Optional context is supplied by the caller, not inferred from accounts:
    content_type='tool_output', cache_prefix_changed=True, and/or
    model_comparison_requested=True. Caller assertions remain unverified.
    """
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if context is not None and not isinstance(context, dict):
        raise TypeError('context must be a dict or None')
    context = context or {}
    if len(text) > MAX_SCAN_CHARS:
        return [{'kind': 'scan_limit', 'evidence': {'characters': len(text),
                 'limit': MAX_SCAN_CHARS, 'content_scanned': False}, 'advisory_only': True}]
    findings = []
    blocks, whitespace = 0, 0
    for match in _JSON_FENCE.finditer(text):
        body = match.group(1)
        try:
            json.loads(body, parse_int=str, parse_float=str, object_pairs_hook=list,
                       parse_constant=_reject_constant)
        except (ValueError, TypeError, RecursionError):
            continue
        count = _outside_whitespace(body)
        if count > 1:
            blocks += 1
            whitespace += count
    if blocks:
        findings.append({'kind': 'json_whitespace', 'evidence': {
            'complete_valid_json_blocks': blocks, 'outside_string_whitespace_characters': whitespace,
            'token_reduction_verified': False, 'format_protection_still_required': True},
            'advisory_only': True})
    if context.get('content_type') == 'tool_output':
        previous, streak, runs, repeats = None, 0, 0, 0
        for line in text.splitlines(keepends=True):
            if line == previous:
                streak += 1
                repeats += 1
                if streak == 2:
                    runs += 1
            else:
                previous, streak = line, 1
        if runs:
            findings.append({'kind': 'exact_adjacent_repetition', 'evidence': {
                'duplicate_runs': runs, 'additional_identical_lines': repeats,
                'content_type_source': 'caller', 'quality_verified': False}, 'advisory_only': True})
    if context.get('cache_prefix_changed') is True:
        findings.append({'kind': 'cache_prefix_review', 'evidence': {
            'prefix_change_reported': True, 'source': 'caller_unverified',
            'provider_cache_hit_verified': False}, 'advisory_only': True})
    if context.get('model_comparison_requested') is True:
        findings.append({'kind': 'model_comparison_review', 'evidence': {
            'comparison_requested': True, 'actual_routing_implemented': False}, 'advisory_only': True})
    return findings

