"""Structural retention checks, not a semantic-quality or relevance oracle.

Checks apply to original bytes OUTSIDE declared deletion spans. An omitted
reference can contain numbers, negations and entities; those are not claimed
preserved globally. Entity checks are simple lexical heuristics, not NER or
confidence probabilities. Originals/patches remain ephemeral caller data.
"""
from collections import Counter
import hashlib
import re

from desktop.structural_compactor import restore

_SCOPES = {'exact_duplicate_context_removal', 'single_target_reference_selection'}
_NUMBERS = re.compile(r'(?<!\w)[+-]?\d+(?:[.,]\d+)*(?:%|[eE][+-]?\d+)?')
_NEGATIONS = re.compile(r"\b(?:not|no|never|neither|nor|without|cannot|can't|don't|mustn't)\b|不得|不能|不要|没有|未|不|无|禁止", re.I)
_ENTITIES = re.compile(r'\b[A-Z][A-Za-z0-9_-]*\b|[\u4e00-\u9fff]{2,8}')
_CONSTRAINTS = re.compile(r'\b(?:must|shall|should|required|only|exactly|at least|at most|maximum|minimum|'
                          r'within|before|after|unless|except|prohibited|forbidden)\b|'
                          r'必须|应当|仅限|只能|至少|至多|最多|最少|不得|禁止|务必|除非|要求', re.I)


def _hash(text):
    return hashlib.sha256(text.encode('utf-8', errors='surrogatepass')).hexdigest()


def _interval(span, length, start='start', end='end'):
    if not isinstance(span, dict):
        return None
    a, b = span.get(start), span.get(end)
    return (a, b) if type(a) is int and type(b) is int and 0 <= a < b <= length else None


def audit(original, candidate, edits, *, scope, dropped_spans, preserved_spans=()):
    """Validate deletion patches and explicitly scoped retention, fail closed.

    Non-target labels are supplied by the deterministic selector; this function
    validates their declared scope, not their semantic irrelevance. No flag in
    this report authenticates input, guarantees answer quality, or proves quota
    savings. Reports contain offsets/hashes/counts, never raw source passages.
    """
    supported = isinstance(scope, str) and scope in _SCOPES
    report = {'passed': False, 'scope': scope if supported else 'unsupported',
              'reasons': [], 'outside_authorized_spans_unchanged': False,
              'roundtrip_verified': False, 'quality_verified': False,
              'semantic_quality_guaranteed': False, 'source_verified': False,
              'relevance_verified': False, 'dropped_spans': [], 'preserved_spans': [],
              'heuristic_checks': {'heuristic_only': True,
                  'entity_method': 'capitalized_tokens_and_cjk_runs_not_named_entity_recognition'}}

    def reject(reason):
        report['reasons'].append(reason)
        return report

    if not isinstance(original, str) or not isinstance(candidate, str) or len(original) > 50000:
        return reject('invalid_or_oversized_text')
    if not supported:
        return reject('unsupported_retention_scope')
    if (not isinstance(edits, list) or not 1 <= len(edits) <= 128
            or not isinstance(dropped_spans, list) or len(dropped_spans) != len(edits)
            or not isinstance(preserved_spans, (list, tuple)) or len(preserved_spans) > 1024):
        return reject('invalid_bounded_span_manifest')
    intervals, pieces, cursor = [], [], 0
    for edit, dropped in zip(edits, dropped_spans):
        interval = _interval(edit, len(original))
        if (interval is None or interval[0] < cursor
                or _interval(dropped, len(original)) != interval
                or edit.get('replacement') != '' or edit.get('original') != original[interval[0]:interval[1]]):
            return reject('invalid_or_non_deletion_patch')
        a, b = interval
        if a and b < len(original) and original[a-1].isalnum() and original[b].isalnum():
            return reject('deletion_would_join_content_tokens')
        pieces.append(original[cursor:a])
        intervals.append(interval)
        cursor = b
    pieces.append(original[cursor:])
    retained = ''.join(pieces)
    if retained != candidate:
        return reject('text_outside_declared_deletions_changed')
    report['outside_authorized_spans_unchanged'] = True
    for dropped, (a, b) in zip(dropped_spans, intervals):
        kind = dropped.get('kind')
        clean = {'start': a, 'end': b, 'kind': kind, 'source_sha256': _hash(original[a:b])}
        if kind == 'exact_duplicate':
            unit = _interval(dropped, len(original), 'unit_start', 'unit_end')
            first = _interval(dropped, len(original), 'retained_start', 'retained_end')
            if (unit is None or first is None or not a <= unit[0] < unit[1] <= b
                    or original[unit[0]:unit[1]] != original[first[0]:first[1]]
                    or (original[a:unit[0]] + original[unit[1]:b]).strip()
                    or any(first[0] < end and start < first[1] for start, end in intervals)):
                return reject('duplicate_has_no_exact_retained_counterpart')
            clean.update(unit_start=unit[0], unit_end=unit[1],
                         retained_start=first[0], retained_end=first[1])
        elif kind == 'non_target_reference' and scope == 'single_target_reference_selection':
            reference = _interval(dropped, len(original), 'reference_start', 'reference_end')
            label, target = dropped.get('label'), dropped.get('target')
            if (reference is None or not reference[0] <= a < b <= reference[1]
                    or not isinstance(label, str) or not isinstance(target, str)
                    or not label.strip() or not target.strip() or len(label) > 80 or len(target) > 80
                    or label.casefold() == target.casefold()):
                return reject('invalid_non_target_reference_scope')
            clean.update(reference_start=reference[0], reference_end=reference[1],
                         label_sha256=_hash(label), target_sha256=_hash(target))
        else:
            return reject('unsupported_deletion_kind')
        report['dropped_spans'].append(clean)
    for span in preserved_spans:
        interval = _interval(span, len(original))
        if interval is None or any(interval[0] < end and start < interval[1] for start, end in intervals):
            return reject('protected_or_relevant_source_span_was_removed')
        report['preserved_spans'].append({'start': interval[0], 'end': interval[1],
                                         'kind': str(span.get('kind', 'retained'))[:40]})
    try:
        recovered = restore({'original': original, 'candidate': candidate, 'edits': edits,
                             'original_sha256': _hash(original), 'candidate_sha256': _hash(candidate)})
    except (ValueError, TypeError):
        return reject('roundtrip_or_offsets_invalid')
    if recovered != original:
        return reject('roundtrip_mismatch')
    report['roundtrip_verified'] = True
    for name, pattern in (('numbers', _NUMBERS), ('negations', _NEGATIONS),
                          ('entity_tokens', _ENTITIES), ('constraints', _CONSTRAINTS)):
        original_tokens = Counter(pattern.findall(original))
        retained_tokens = Counter(pattern.findall(retained))
        candidate_tokens = Counter(pattern.findall(candidate))
        report['heuristic_checks'][name] = {
            'retained_material_matches': retained_tokens == candidate_tokens,
            'original_count': sum(original_tokens.values()),
            'retained_count': sum(retained_tokens.values()),
            'global_inventory_unchanged': original_tokens == candidate_tokens,
            'scope': 'original_outside_declared_deletion_spans'}
    report.update(passed=True,
                  omission_warning='Deleted material is not preserved in the candidate; reversibility requires the original patches.',
                  relevance_method='exact_retained_duplicate' if scope == 'exact_duplicate_context_removal'
                  else 'explicit_labels_and_query_heuristic_not_semantic_proof')
    return report

