"""Bounded in-memory exact-failure retry guard. No raw error persistence.

The caller must enforce block_next_retry before scheduling another invocation.
This tracker does not cancel tools or imply that it has changed an agent loop.
Deduplication lasts only for the bounded recent-event window of this instance.
"""
from collections import OrderedDict
import hashlib
import hmac
import json
import secrets
import threading


class RetryTracker:
    def __init__(self, max_sessions=128, max_events=4096):
        if type(max_sessions) is not int or not 1 <= max_sessions <= 10000:
            raise ValueError('max_sessions must be 1–10000')
        if type(max_events) is not int or not 1 <= max_events <= 100000:
            raise ValueError('max_events must be 1–100000')
        self.max_sessions, self.max_events = max_sessions, max_events
        self._key = secrets.token_bytes(32)
        self._sessions, self._events = OrderedDict(), OrderedDict()
        self._lock = threading.RLock()

    def _digest(self, *values):
        payload = json.dumps(values, ensure_ascii=True, separators=(',', ':')).encode('ascii')
        return hmac.new(self._key, payload, hashlib.sha256).hexdigest()

    def record(self, event_id, session_id, tool, action, error, success=False):
        with self._lock:
            return self._record(event_id, session_id, tool, action, error, success)

    def _record(self, event_id, session_id, tool, action, error, success):
        for name, value, limit in (('event_id', event_id, 512), ('session_id', session_id, 512),
                                   ('tool', tool, 256), ('action', action, 65536)):
            if not isinstance(value, str) or not value or len(value) > limit:
                raise ValueError(name + ' must be a bounded nonempty string')
        if type(success) is not bool:
            raise TypeError('success must be boolean')
        if error is None and success:
            error = ''
        if not isinstance(error, str) or len(error) > 65536 or (not error and not success):
            raise ValueError('Failed events need bounded nonempty error text')
        session_key = self._digest('session', session_id)
        event_key = (session_key, self._digest('event', event_id))
        if event_key in self._events:
            # A duplicate must not rewind a newer success/strategy state. The
            # original event result remains available as inert evidence only.
            original = self._events[event_key]
            current = self._sessions.get(session_key, {})
            streak = current.get('streak', 0)
            self._events.move_to_end(event_key)
            return {**original, 'duplicate': True, 'consecutive_failures': streak,
                    'block_next_retry': streak >= 2, 'blocked': streak >= 2,
                    'reset': False, 'reason': 'duplicate_event_ignored'}
        fingerprint = self._digest('failure', tool, action, error)
        previous = self._sessions.get(session_key)
        same = previous is not None and previous['fingerprint'] == fingerprint
        if success:
            streak, reason, reset = 0, 'success_reset', True
            fingerprint = None
        elif same:
            streak = min(2, previous['streak'] + 1)
            reason, reset = 'identical_failure_limit' if streak >= 2 else 'first_failure', False
        else:
            streak, reason = 1, 'strategy_or_error_changed' if previous else 'first_failure'
            reset = previous is not None
        self._sessions[session_key] = {'fingerprint': fingerprint, 'streak': streak}
        self._sessions.move_to_end(session_key)
        while len(self._sessions) > self.max_sessions:
            self._sessions.popitem(last=False)
        result = {'event_fingerprint': event_key[1], 'session_fingerprint': session_key,
                  'action_error_fingerprint': fingerprint, 'consecutive_failures': streak,
                  'streak_capped_at': 2, 'duplicate': False, 'reset': reset,
                  'block_next_retry': streak >= 2, 'blocked': streak >= 2,
                  'reason': reason, 'requires_caller_enforcement': True,
                  'deduplication_scope': 'bounded_in_memory_window', 'raw_error_retained': False}
        self._events[event_key] = dict(result)
        while len(self._events) > self.max_events:
            self._events.popitem(last=False)
        return result

    @property
    def retained_counts(self):
        with self._lock:
            return {'sessions': len(self._sessions), 'events': len(self._events)}
